<?php
declare(strict_types=1);namespace Atlas\Platform\Workflows\Catalog;final class WordPressWorkflowCatalogRepository implements WorkflowCatalogRepository{public function __construct(private object$db){}public function publishedForContext(?string$organizationId,int$limit=50):array{$w=$this->db->prefix.'atlas_workflows';$v=$this->db->prefix.'atlas_workflow_versions';$s=$this->db->prefix.'atlas_workflow_steps';$limit=max(1,min(50,$limit));$rows=$this->db->get_results($this->db->prepare("SELECT w.id,w.scope,v.title,v.summary,v.version_number,(SELECT COUNT(*) FROM `{$s}` steps WHERE steps.workflow_version_id=v.id) step_count FROM `{$w}` w INNER JOIN `{$v}` v ON v.id=w.current_version_id WHERE v.status='published' AND (w.scope IN ('platform','public') OR (w.scope='organization' AND w.organization_id=%s)) ORDER BY CASE WHEN w.scope='organization' THEN 0 ELSE 1 END,v.title,w.id LIMIT %d",$organizationId??'',$limit),ARRAY_A);if(!is_array($rows)){return[];}return array_map(static fn(array$r):WorkflowSummary=>new WorkflowSummary((string)$r['id'],(string)$r['title'],(string)$r['summary'],(string)$r['scope'],(int)$r['version_number'],(int)$r['step_count']),$rows);}}
